import React, { useState, useEffect } from 'react';
import api from '../services/api';

const MONTHS = ['Janvier','Février','Mars','Avril','Mai','Juin','Juillet','Août','Septembre','Octobre','Novembre','Décembre'];
const DAYS   = ['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'];

/* ════════════════════════════════════════════════
   CALENDRIER — synchronisé avec les dispos réelles
════════════════════════════════════════════════ */
function SmartCalendar({ dispos }) {
  const today = new Date();

  // Trouver le mois le plus pertinent : celui qui a le plus de dispos futures
  const initialMonth = () => {
    if (!dispos || dispos.length === 0) return { y: today.getFullYear(), m: today.getMonth() };
    // Prendre la première dispo future
    const futures = dispos
      .filter(d => d.date_specifique)
      .map(d => new Date(d.date_specifique + 'T00:00:00'))
      .filter(d => d >= new Date(today.getFullYear(), today.getMonth(), 1))
      .sort((a, b) => a - b);
    if (futures.length > 0) return { y: futures[0].getFullYear(), m: futures[0].getMonth() };
    return { y: today.getFullYear(), m: today.getMonth() };
  };

  const init = initialMonth();
  const [year, setYear]   = useState(init.y);
  const [month, setMonth] = useState(init.m);

  // Re-synchroniser si les dispos changent
  useEffect(() => {
    const i = initialMonth();
    setYear(i.y);
    setMonth(i.m);
  }, [dispos.length]);

  const firstDay    = new Date(year, month, 1).getDay();
  const offset      = (firstDay + 6) % 7; // Lundi = 0
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const cells       = Array.from({ length: 42 }, (_, i) => i - offset + 1);

  // Construire un map date → statut pour ce mois
  const dayMap = {};
  dispos.forEach(d => {
    if (!d.date_specifique) return;
    const dt = new Date(d.date_specifique + 'T00:00:00');
    if (dt.getFullYear() !== year || dt.getMonth() !== month) return;
    const day = dt.getDate();
    const complet = d.nb_inscrits >= d.nb_max_etudiants;
    // Si plusieurs séances le même jour : complet seulement si TOUTES sont complètes
    if (dayMap[day] === undefined) {
      dayMap[day] = complet ? 'complet' : 'dispo';
    } else if (dayMap[day] === 'complet' && !complet) {
      dayMap[day] = 'dispo'; // Au moins une place libre → dispo
    }
  });

  const isToday = (d) => d === today.getDate() && month === today.getMonth() && year === today.getFullYear();

  function prev() {
    if (month === 0) { setMonth(11); setYear(y => y - 1); }
    else setMonth(m => m - 1);
  }
  function next() {
    if (month === 11) { setMonth(0); setYear(y => y + 1); }
    else setMonth(m => m + 1);
  }

  return (
    <div>
      {/* Navigation */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
        <button onClick={prev} style={{ width: 32, height: 32, borderRadius: 8, background: 'var(--surface2)', border: '1px solid var(--border)', color: 'var(--text)', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>‹</button>
        <div style={{ fontWeight: 700, fontSize: '.95rem' }}>{MONTHS[month]} {year}</div>
        <button onClick={next} style={{ width: 32, height: 32, borderRadius: 8, background: 'var(--surface2)', border: '1px solid var(--border)', color: 'var(--text)', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>›</button>
      </div>

      {/* Légende */}
      <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 14, fontSize: '.72rem', marginBottom: 10 }}>
        <span style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
          <span style={{ width: 8, height: 8, borderRadius: '50%', background: '#43e97b', display: 'inline-block' }} />
          Disponible
        </span>
        <span style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
          <span style={{ width: 8, height: 8, borderRadius: '50%', background: '#ff6584', display: 'inline-block' }} />
          Complet
        </span>
      </div>

      {/* Jours de semaine */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7,1fr)', gap: 2, marginBottom: 4 }}>
        {DAYS.map(d => (
          <div key={d} style={{ textAlign: 'center', fontSize: '.65rem', fontWeight: 700, color: 'var(--text2)', textTransform: 'uppercase', padding: '4px 0' }}>{d}</div>
        ))}
      </div>

      {/* Grille des jours */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7,1fr)', gap: 2 }}>
        {cells.map((d, i) => {
          const valid   = d >= 1 && d <= daysInMonth;
          const statut  = valid ? dayMap[d] : undefined;
          const td      = valid && isToday(d);

          let bg = 'transparent', color = 'var(--text2)', border = '1px solid transparent';
          if (!valid) { color = 'transparent'; }
          else if (statut === 'dispo')   { bg = 'rgba(67,233,123,0.15)';  color = '#43e97b'; border = '1px solid rgba(67,233,123,0.3)'; }
          else if (statut === 'complet') { bg = 'rgba(255,101,132,0.15)'; color = '#ff6584'; border = '1px solid rgba(255,101,132,0.3)'; }
          if (td) { border = '2px solid #6c63ff'; color = statut ? color : '#6c63ff'; }

          return (
            <div key={i} style={{ aspectRatio: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', borderRadius: 8, fontSize: '.78rem', fontWeight: statut || td ? 700 : 400, background: bg, color, border, transition: '.15s' }}>
              {valid ? d : ''}
            </div>
          );
        })}
      </div>

      {/* Légende du mois */}
      {Object.keys(dayMap).length > 0 && (
        <div style={{ marginTop: 14, padding: '10px 12px', background: 'var(--surface2)', borderRadius: 10, fontSize: '.75rem', color: 'var(--text2)' }}>
          <span style={{ color: '#43e97b', fontWeight: 700 }}>{Object.values(dayMap).filter(v => v === 'dispo').length}</span> jour{Object.values(dayMap).filter(v => v === 'dispo').length > 1 ? 's' : ''} avec places disponibles
          {Object.values(dayMap).filter(v => v === 'complet').length > 0 && (
            <span> · <span style={{ color: '#ff6584', fontWeight: 700 }}>{Object.values(dayMap).filter(v => v === 'complet').length}</span> complet{Object.values(dayMap).filter(v => v === 'complet').length > 1 ? 's' : ''}</span>
          )}
        </div>
      )}
    </div>
  );
}

/* ════════════════════════════════════════════════
   PAGE DISPONIBILITÉS
════════════════════════════════════════════════ */
const EMPTY_DISPO = {
  date_specifique: '',
  heure_debut: '09:00',
  heure_fin: '10:00',
  nb_max_etudiants: 1,
  mode_seance: 'presentiel',
};

export default function Disponibilites() {
  const [dispos, setDispos]       = useState([]);
  const [profile, setProfile]     = useState(null);
  const [loading, setLoading]     = useState(true);
  const [showForm, setShowForm]   = useState(false);
  const [newDispo, setNewDispo]   = useState({ ...EMPTY_DISPO });
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => { fetchAll(); }, []);

  const fetchAll = async () => {
    try {
      const [resDispos, resProfile] = await Promise.all([
        api.get('/api/professeurs/me/disponibilites'),
        api.get('/api/professeurs/me'),
      ]);
      const prof = resProfile.data ?? null;
      setDispos(resDispos.data ?? []);
      setProfile(prof);
      const mode = prof?.mode_enseignement;
      setNewDispo(prev => ({
        ...prev,
        mode_seance: mode === 'les_deux' ? 'presentiel' : (mode || 'presentiel'),
      }));
    } catch (e) {
      console.error('Erreur chargement:', e);
    } finally {
      setLoading(false);
    }
  };

  const fetchDispos = async () => {
    try {
      const res = await api.get('/api/professeurs/me/disponibilites');
      setDispos(res.data ?? []);
    } catch (e) {
      console.error(e);
    }
  };

  const handleAdd = async (e) => {
    e.preventDefault();
    if (!getDuration(newDispo.heure_debut, newDispo.heure_fin)) {
      alert("L'heure de fin doit être après l'heure de début.");
      return;
    }
    setSubmitting(true);
    try {
      await api.post('/api/professeurs/me/disponibilites', {
        ...newDispo,
        nb_max_etudiants: parseInt(newDispo.nb_max_etudiants, 10),
      });
      setShowForm(false);
      resetForm();
      await fetchDispos();
      alert('✅ Séance ajoutée !');
    } catch (e) {
      alert('Erreur : ' + (e.response?.data?.detail || e.message));
    } finally {
      setSubmitting(false);
    }
  };

  const handleDelete = async (id) => {
    if (!id || !window.confirm('Supprimer ce créneau ?')) return;
    try {
      await api.delete(`/api/professeurs/me/disponibilites/${id}`);
      setDispos(prev => prev.filter(d => d.id !== id));
    } catch (e) {
      alert('Erreur : ' + (e.response?.data?.detail || e.message));
      await fetchDispos();
    }
  };

  const resetForm = () => {
    const mode = profile?.mode_enseignement;
    setNewDispo({ ...EMPTY_DISPO, mode_seance: mode === 'les_deux' ? 'presentiel' : (mode || 'presentiel') });
  };

  const getDuration = (debut, fin) => {
    if (!debut || !fin) return null;
    const [h1, m1] = debut.split(':').map(Number);
    const [h2, m2] = fin.split(':').map(Number);
    const diff = (h2 * 60 + m2) - (h1 * 60 + m1);
    if (diff <= 0) return null;
    const h = Math.floor(diff / 60), m = diff % 60;
    return h > 0 ? `${h}h${m > 0 ? String(m).padStart(2, '0') : ''}` : `${m}min`;
  };

  const getModeInfo = (mode) => {
    if (mode === 'en_ligne') return { icon: '🌐', label: 'En ligne',   color: '#38bdf8', bg: 'rgba(56,189,248,0.12)', border: 'rgba(56,189,248,0.3)' };
    return { icon: '🏫', label: 'Présentiel', color: '#43e97b', bg: 'rgba(67,233,123,0.12)', border: 'rgba(67,233,123,0.3)' };
  };

  const formatDate = (str) => str
    ? new Date(str + 'T00:00:00').toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })
    : '';

  const profMode       = profile?.mode_enseignement;
  const showModeChoice = profMode === 'les_deux';

  // Grouper par date
  const grouped = dispos.reduce((acc, d) => {
    const key = d.date_specifique || 'Sans date';
    if (!acc[key]) acc[key] = [];
    acc[key].push(d);
    return acc;
  }, {});

  const inp = {
    background: 'var(--surface2)', border: '1px solid var(--border)',
    borderRadius: 10, color: 'var(--text)', padding: '10px 14px',
    fontSize: '.9rem', outline: 'none', width: '100%', boxSizing: 'border-box',
  };

  const lbl = (txt) => (
    <div style={{ fontSize: '.75rem', fontWeight: 700, color: 'var(--text2)', textTransform: 'uppercase', letterSpacing: '.07em', marginBottom: 8 }}>
      {txt}
    </div>
  );

  if (loading) return <div style={{ padding: 60, textAlign: 'center', color: 'var(--text2)' }}>⏳ Chargement...</div>;

  return (
    <div style={{ padding: 32, maxWidth: 1100, margin: '0 auto' }}>

      {/* HEADER */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 28 }}>
        <div>
          <h2 style={{ fontFamily: 'Syne', margin: 0, fontSize: '1.6rem' }}>🗓 Mes disponibilités</h2>
          <p style={{ color: 'var(--text2)', fontSize: '.85rem', marginTop: 4 }}>
            {dispos.length} séance{dispos.length !== 1 ? 's' : ''} planifiée{dispos.length !== 1 ? 's' : ''}
          </p>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
          {profMode && (() => {
            const colors = {
              en_ligne:   { bg: 'rgba(56,189,248,0.1)',  border: 'rgba(56,189,248,0.3)',  color: '#38bdf8', icon: '🌐', label: 'En ligne' },
              presentiel: { bg: 'rgba(67,233,123,0.1)',  border: 'rgba(67,233,123,0.3)',  color: '#43e97b', icon: '🏫', label: 'Présentiel' },
              les_deux:   { bg: 'rgba(108,99,255,0.1)',  border: 'rgba(108,99,255,0.3)',  color: '#6c63ff', icon: '🔀', label: 'En ligne & Présentiel' },
            }[profMode];
            return (
              <div style={{ padding: '8px 14px', borderRadius: 20, background: colors.bg, border: `1px solid ${colors.border}`, fontSize: '.82rem', fontWeight: 600, color: colors.color }}>
                {colors.icon} {colors.label}
              </div>
            );
          })()}
          <button
            onClick={() => setShowForm(true)}
            style={{ background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', color: '#fff', border: 'none', padding: '11px 22px', borderRadius: 12, fontWeight: 600, cursor: 'pointer', fontSize: '.9rem' }}
          >
            + Nouvelle séance
          </button>
        </div>
      </div>

      {/* STATS */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 16, marginBottom: 28 }}>
        {[
          { icon: '📅', val: dispos.length, lbl: 'Séances planifiées', color: '#6c63ff', bg: 'rgba(108,99,255,.1)' },
          { icon: '👥', val: dispos.reduce((s, d) => s + (d.nb_max_etudiants || 0), 0), lbl: 'Places totales', color: '#43e97b', bg: 'rgba(67,233,123,.1)' },
          { icon: '📊', val: dispos.reduce((s, d) => s + (d.nb_inscrits || 0), 0), lbl: 'Inscrits total', color: '#f59e0b', bg: 'rgba(245,158,11,.1)' },
        ].map(s => (
          <div key={s.lbl} style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, padding: '16px 20px', display: 'flex', alignItems: 'center', gap: 14 }}>
            <div style={{ width: 44, height: 44, borderRadius: 12, background: s.bg, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.2rem' }}>{s.icon}</div>
            <div>
              <div style={{ fontFamily: 'Syne', fontSize: '1.5rem', fontWeight: 800, color: s.color }}>{s.val}</div>
              <div style={{ fontSize: '.78rem', color: 'var(--text2)' }}>{s.lbl}</div>
            </div>
          </div>
        ))}
      </div>

      {/* GRILLE PRINCIPALE */}
      <div style={{ display: 'grid', gridTemplateColumns: '1.4fr 0.6fr', gap: 24 }}>

        {/* LISTE */}
        <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
          <h3 style={{ marginTop: 0, marginBottom: 20 }}>📋 Séances planifiées</h3>

          {dispos.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '50px 20px', color: 'var(--text2)' }}>
              <div style={{ fontSize: '2.5rem', marginBottom: 12 }}>📭</div>
              <div style={{ fontWeight: 600, marginBottom: 6 }}>Aucune séance planifiée</div>
              <div style={{ fontSize: '.82rem' }}>Cliquez sur "+ Nouvelle séance" pour commencer</div>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
              {Object.entries(grouped)
                .sort(([a], [b]) => a.localeCompare(b))
                .map(([dateKey, seances]) => (
                  <div key={dateKey} style={{ marginBottom: 8 }}>
                    <div style={{ fontSize: '.72rem', fontWeight: 700, color: 'var(--text2)', textTransform: 'uppercase', letterSpacing: '.08em', padding: '6px 4px', borderBottom: '1px solid var(--border)', marginBottom: 8 }}>
                      📆 {dateKey !== 'Sans date' ? formatDate(dateKey) : 'Sans date'}
                    </div>

                    {seances.map(d => {
                      const mi   = getModeInfo(d.mode_seance || profMode);
                      const dur  = getDuration(d.heure_debut?.slice(0, 5), d.heure_fin?.slice(0, 5));
                      const pct  = d.nb_max_etudiants > 0 ? Math.round((d.nb_inscrits / d.nb_max_etudiants) * 100) : 0;
                      const full = pct >= 100;

                      return (
                        <div key={d.id} style={{
                          background: 'var(--surface2)', padding: '14px 16px',
                          borderRadius: 14, border: '1px solid var(--border)',
                          borderLeft: `3px solid ${full ? '#ff6584' : mi.color}`,
                          display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                          marginBottom: 8,
                        }}>
                          <div style={{ flex: 1 }}>
                            <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 6 }}>
                              <span style={{ fontWeight: 700, color: 'var(--accent)', fontSize: '.95rem' }}>
                                🕒 {d.heure_debut?.slice(0, 5)} – {d.heure_fin?.slice(0, 5)}
                              </span>
                              {dur && (
                                <span style={{ fontSize: '.7rem', background: 'rgba(108,99,255,0.15)', color: '#6c63ff', padding: '2px 8px', borderRadius: 20, fontWeight: 600 }}>
                                  ⏱ {dur}
                                </span>
                              )}
                            </div>
                            <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 8 }}>
                              <span style={{ fontSize: '.73rem', fontWeight: 700, padding: '3px 10px', borderRadius: 20, background: mi.bg, color: mi.color }}>
                                {mi.icon} {mi.label}
                              </span>
                            </div>
                            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                              <span style={{ fontSize: '.75rem', color: 'var(--text2)', whiteSpace: 'nowrap' }}>
                                👥 {d.nb_inscrits}/{d.nb_max_etudiants}
                              </span>
                              <div style={{ width: 100, height: 5, background: 'var(--border)', borderRadius: 3, overflow: 'hidden' }}>
                                <div style={{ height: '100%', borderRadius: 3, width: `${Math.min(pct, 100)}%`, background: full ? '#ff6584' : pct >= 70 ? '#f59e0b' : '#43e97b', transition: 'width .3s' }} />
                              </div>
                              <span style={{ fontSize: '.7rem', color: full ? '#ff6584' : 'var(--text2)', fontWeight: full ? 700 : 400 }}>
                                {full ? '🔴 Complet' : `${100 - pct}% libre`}
                              </span>
                            </div>
                          </div>
                          <button
                            onClick={() => handleDelete(d.id)}
                            style={{ background: 'rgba(255,101,132,0.1)', color: '#ff6584', border: '1px solid rgba(255,101,132,0.2)', padding: '8px 10px', borderRadius: 10, cursor: 'pointer', fontSize: '.9rem', marginLeft: 14, flexShrink: 0 }}
                          >🗑</button>
                        </div>
                      );
                    })}
                  </div>
                ))}
            </div>
          )}
        </div>

        {/* CALENDRIER — synchronisé */}
        <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24, alignSelf: 'start', position: 'sticky', top: 80 }}>
          <h3 style={{ marginTop: 0, marginBottom: 20 }}>📅 Calendrier</h3>
          <SmartCalendar dispos={dispos} />
        </div>
      </div>

      {/* ═══════════════ MODAL ═══════════════ */}
      {showForm && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.85)', zIndex: 2000, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20 }}>
          <div style={{ background: 'var(--surface)', borderRadius: 24, border: '1px solid var(--border)', width: '100%', maxWidth: 480, maxHeight: '90vh', overflowY: 'auto', padding: 32 }}>

            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 24 }}>
              <h3 style={{ margin: 0, fontFamily: 'Syne', fontSize: '1.2rem' }}>📅 Nouvelle séance</h3>
              <button onClick={() => { setShowForm(false); resetForm(); }} style={{ width: 32, height: 32, borderRadius: 8, background: 'var(--surface2)', border: '1px solid var(--border)', cursor: 'pointer', color: 'var(--text)', fontSize: '1rem', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>✕</button>
            </div>

            <form onSubmit={handleAdd} style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>

              {/* DATE */}
              <div>
                {lbl('📆 Date de la séance')}
                <input type="date" style={inp} required min={new Date().toISOString().split('T')[0]} value={newDispo.date_specifique} onChange={e => setNewDispo({ ...newDispo, date_specifique: e.target.value })} />
                {newDispo.date_specifique && (
                  <div style={{ marginTop: 6, fontSize: '.8rem', color: '#6c63ff', fontWeight: 600 }}>
                    📍 {formatDate(newDispo.date_specifique)}
                  </div>
                )}
              </div>

              {/* HORAIRES */}
              <div>
                {lbl('🕒 Horaires')}
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
                  <div>
                    <div style={{ fontSize: '.75rem', color: 'var(--text2)', marginBottom: 5 }}>Début</div>
                    <input type="time" style={inp} required value={newDispo.heure_debut} onChange={e => setNewDispo({ ...newDispo, heure_debut: e.target.value })} />
                  </div>
                  <div>
                    <div style={{ fontSize: '.75rem', color: 'var(--text2)', marginBottom: 5 }}>Fin</div>
                    <input type="time" style={inp} required value={newDispo.heure_fin} onChange={e => setNewDispo({ ...newDispo, heure_fin: e.target.value })} />
                  </div>
                </div>
                <div style={{ marginTop: 8 }}>
                  {getDuration(newDispo.heure_debut, newDispo.heure_fin) ? (
                    <span style={{ fontSize: '.8rem', background: 'rgba(108,99,255,0.15)', color: '#6c63ff', padding: '3px 12px', borderRadius: 20, fontWeight: 700 }}>
                      ⏱ Durée : {getDuration(newDispo.heure_debut, newDispo.heure_fin)}
                    </span>
                  ) : newDispo.heure_debut && newDispo.heure_fin ? (
                    <span style={{ fontSize: '.8rem', color: '#ff6584' }}>⚠️ L'heure de fin doit être après l'heure de début</span>
                  ) : null}
                </div>
              </div>

              {/* MODE */}
              <div>
                {lbl('🎓 Mode d\'enseignement')}
                {showModeChoice ? (
                  <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
                    {[
                      { value: 'en_ligne',   icon: '🌐', label: 'En ligne',   color: '#38bdf8', bg: 'rgba(56,189,248,0.1)',  border: 'rgba(56,189,248,0.4)' },
                      { value: 'presentiel', icon: '🏫', label: 'Présentiel', color: '#43e97b', bg: 'rgba(67,233,123,0.1)',  border: 'rgba(67,233,123,0.4)' },
                    ].map(m => {
                      const active = newDispo.mode_seance === m.value;
                      return (
                        <div key={m.value} onClick={() => setNewDispo({ ...newDispo, mode_seance: m.value })}
                          style={{ padding: '14px 16px', borderRadius: 14, cursor: 'pointer', textAlign: 'center', border: active ? `2px solid ${m.border}` : '2px solid var(--border)', background: active ? m.bg : 'var(--surface2)', transition: 'all .18s' }}>
                          <div style={{ fontSize: '1.5rem', marginBottom: 4 }}>{m.icon}</div>
                          <div style={{ fontWeight: 700, fontSize: '.88rem', color: active ? m.color : 'var(--text)' }}>{m.label}</div>
                          {active && <div style={{ fontSize: '.7rem', color: m.color, marginTop: 3 }}>✓ Sélectionné</div>}
                        </div>
                      );
                    })}
                  </div>
                ) : (
                  <div style={{ padding: '12px 16px', borderRadius: 12, background: profMode === 'en_ligne' ? 'rgba(56,189,248,0.08)' : 'rgba(67,233,123,0.08)', border: `1px solid ${profMode === 'en_ligne' ? 'rgba(56,189,248,0.25)' : 'rgba(67,233,123,0.25)'}`, display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                    <span style={{ fontWeight: 700, color: profMode === 'en_ligne' ? '#38bdf8' : '#43e97b', fontSize: '.9rem' }}>
                      {profMode === 'en_ligne' ? '🌐 En ligne' : '🏫 Présentiel'}
                    </span>
                    {profMode === 'en_ligne' && profile?.tarif_en_ligne && <span style={{ fontSize: '.8rem', color: 'var(--text2)' }}>💰 {profile.tarif_en_ligne} DT/h</span>}
                    {profMode === 'presentiel' && profile?.tarif_presentiel && <span style={{ fontSize: '.8rem', color: 'var(--text2)' }}>💰 {profile.tarif_presentiel} DT/h</span>}
                  </div>
                )}

                {(newDispo.mode_seance === 'en_ligne' || profMode === 'en_ligne') && profile?.tarif_en_ligne && showModeChoice && newDispo.mode_seance === 'en_ligne' && (
                  <div style={{ marginTop: 10, padding: '8px 14px', background: 'rgba(56,189,248,0.07)', border: '1px solid rgba(56,189,248,0.2)', borderRadius: 10, fontSize: '.8rem', color: '#38bdf8', fontWeight: 600 }}>
                    💰 Tarif appliqué : {profile.tarif_en_ligne} DT/h
                  </div>
                )}
                {showModeChoice && newDispo.mode_seance === 'presentiel' && profile?.tarif_presentiel && (
                  <div style={{ marginTop: 10, padding: '8px 14px', background: 'rgba(67,233,123,0.07)', border: '1px solid rgba(67,233,123,0.2)', borderRadius: 10, fontSize: '.8rem', color: '#43e97b', fontWeight: 600 }}>
                    💰 Tarif appliqué : {profile.tarif_presentiel} DT/h
                  </div>
                )}
              </div>

              {/* CAPACITÉ */}
              <div>
                {lbl('👥 Capacité maximale')}
                <div style={{ display: 'flex', gap: 8, marginBottom: 10 }}>
                  {[1, 2, 3, 5, 10].map(n => (
                    <button key={n} type="button" onClick={() => setNewDispo({ ...newDispo, nb_max_etudiants: n })}
                      style={{ flex: 1, padding: '9px 0', borderRadius: 10, cursor: 'pointer', fontWeight: 700, fontSize: '.85rem', transition: 'all .15s', border: newDispo.nb_max_etudiants === n ? '2px solid var(--accent)' : '2px solid var(--border)', background: newDispo.nb_max_etudiants === n ? 'rgba(108,99,255,0.15)' : 'var(--surface2)', color: newDispo.nb_max_etudiants === n ? '#6c63ff' : 'var(--text)' }}>
                      {n === 1 ? '👤 1' : n}
                    </button>
                  ))}
                </div>
                <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                  <input type="number" min="1" max="50" style={inp} placeholder="Ou saisir un nombre..." value={newDispo.nb_max_etudiants} onChange={e => setNewDispo({ ...newDispo, nb_max_etudiants: parseInt(e.target.value) || 1 })} />
                  <span style={{ whiteSpace: 'nowrap', fontSize: '.85rem', color: 'var(--text2)' }}>étudiant{newDispo.nb_max_etudiants > 1 ? 's' : ''}</span>
                </div>
                {newDispo.nb_max_etudiants > 1 && (
                  <div style={{ marginTop: 6, fontSize: '.78rem', color: '#f59e0b' }}>
                    ℹ️ Séance de groupe ({newDispo.nb_max_etudiants} étudiants max)
                  </div>
                )}
              </div>

              {/* RÉCAP */}
              {newDispo.date_specifique && getDuration(newDispo.heure_debut, newDispo.heure_fin) && (
                <div style={{ background: 'rgba(108,99,255,0.07)', border: '1px solid rgba(108,99,255,0.2)', borderRadius: 14, padding: 16 }}>
                  <div style={{ fontWeight: 700, fontSize: '.75rem', color: '#6c63ff', textTransform: 'uppercase', letterSpacing: '.06em', marginBottom: 10 }}>📋 Récapitulatif</div>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: 5, fontSize: '.85rem', color: 'var(--text)' }}>
                    <div>📆 {formatDate(newDispo.date_specifique)}</div>
                    <div>🕒 {newDispo.heure_debut} → {newDispo.heure_fin} ({getDuration(newDispo.heure_debut, newDispo.heure_fin)})</div>
                    <div>{newDispo.mode_seance === 'en_ligne' ? '🌐 En ligne' : '🏫 Présentiel'}</div>
                    <div>👥 {newDispo.nb_max_etudiants} étudiant{newDispo.nb_max_etudiants > 1 ? 's' : ''} max</div>
                  </div>
                </div>
              )}

              {/* BOUTONS */}
              <div style={{ display: 'flex', gap: 12 }}>
                <button type="submit" disabled={submitting || !getDuration(newDispo.heure_debut, newDispo.heure_fin)}
                  style={{ flex: 2, padding: 13, borderRadius: 12, border: 'none', fontWeight: 700, fontSize: '.9rem', cursor: (submitting || !getDuration(newDispo.heure_debut, newDispo.heure_fin)) ? 'not-allowed' : 'pointer', background: (submitting || !getDuration(newDispo.heure_debut, newDispo.heure_fin)) ? 'var(--border)' : 'linear-gradient(135deg,#6c63ff,#8b5cf6)', color: '#fff' }}>
                  {submitting ? '⏳ Création...' : '✅ Créer la séance'}
                </button>
                <button type="button" onClick={() => { setShowForm(false); resetForm(); }}
                  style={{ flex: 1, padding: 13, borderRadius: 12, border: '1px solid var(--border)', background: 'var(--surface2)', color: 'var(--text)', fontWeight: 600, cursor: 'pointer' }}>
                  Annuler
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
